<?php
namespace Marquesano\Admin\Panel;
defined( 'ABSPATH' ) || exit;

function screen_orders() {
	echo '<div class="mp-heading"><div><p class="mp-eyebrow">OPERAÇÃO</p><h1>Pedidos</h1></div></div><form method="get" class="mp-filters">';
	input( 'q', 'ID do pedido ou e-mail de cobrança', text( $_GET, 'q' ), 'search' ); $choices = array( '' => 'Todos' ); foreach ( wc_get_order_statuses() as $key => $label ) { $choices[ $key ] = $label; } select( 'status', 'Status', $choices, text( $_GET, 'status' ) ); echo '<button>Filtrar</button></form>';
	$args = array( 'type' => 'shop_order', 'limit' => 15, 'paginate' => true, 'paged' => max( 1, number( $_GET, 'pg', 1 ) ), 'orderby' => 'date', 'order' => 'DESC' );
	$status = text( $_GET, 'status' ); if ( isset( wc_get_order_statuses()[ $status ] ) ) { $args['status'] = $status; }
	$search = text( $_GET, 'q' ); if ( $search ) { if ( ctype_digit( $search ) ) { $args['include'] = array( (int) $search ); } elseif ( is_email( $search ) ) { $args['billing_email'] = $search; } else { echo '<div class="mp-notice">Informe o ID numérico ou um e-mail completo.</div>'; return; } }
	$result = wc_get_orders( $args ); echo '<div class="mp-card mp-table"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Data</th><th>Status</th><th>Total</th><th></th></tr></thead><tbody>';
	foreach ( $result->orders as $order ) { $date = $order->get_date_created(); echo '<tr><td>#' . esc_html( $order->get_order_number() ) . '</td><td>' . esc_html( $order->get_formatted_billing_full_name() ) . '</td><td>' . esc_html( $date ? wc_format_datetime( $date ) : '—' ) . '</td><td><span class="mp-badge">' . esc_html( wc_get_order_status_name( $order->get_status() ) ) . '</span></td><td>' . wp_kses_post( $order->get_formatted_order_total() ) . '</td><td><a href="' . esc_url( url( 'pedido/' . $order->get_id() ) ) . '">Abrir</a></td></tr>'; }
	if ( ! $result->orders ) { echo '<tr><td colspan="6">Nenhum pedido encontrado.</td></tr>'; } echo '</tbody></table></div>'; pages( $args['paged'], $result->max_num_pages );
}
function screen_order() {
	$order = Commerce::order( Router::$id ); $date = $order->get_date_modified();
	echo '<div class="mp-heading"><div><p class="mp-eyebrow">PEDIDOS / ' . esc_html( wc_get_order_status_name( $order->get_status() ) ) . '</p><h1>Pedido #' . esc_html( $order->get_order_number() ) . '</h1></div><a href="' . esc_url( url( 'pedidos' ) ) . '">Voltar aos pedidos</a></div><div class="mp-form-grid"><section class="mp-card"><h2>Contato e cobrança</h2><p>' . wp_kses_post( $order->get_formatted_billing_address() ) . '</p><p>' . esc_html( $order->get_billing_email() ) . '</p><p>' . esc_html( $order->get_billing_phone() ) . '</p></section><section class="mp-card"><h2>Entrega e pagamento</h2><p>' . wp_kses_post( $order->get_formatted_shipping_address() ) . '</p><p>' . esc_html( $order->get_payment_method_title() ) . '</p><p>' . esc_html( $order->is_paid() ? 'Marcado como pago no WooCommerce' : 'Sem confirmação de pagamento no status atual' ) . '</p></section></div><section class="mp-card mp-table"><h2>Itens</h2><table><thead><tr><th>Produto</th><th>Quantidade</th><th>Total</th></tr></thead><tbody>';
	foreach ( $order->get_items() as $item ) { echo '<tr><td>' . esc_html( $item->get_name() ) . '</td><td>' . esc_html( $item->get_quantity() ) . '</td><td>' . wp_kses_post( wc_price( $item->get_total() + $item->get_total_tax(), array( 'currency' => $order->get_currency() ) ) ) . '</td></tr>'; }
	echo '</tbody></table><dl class="mp-order-totals">'; foreach ( $order->get_order_item_totals() as $total ) { echo '<div><dt>' . wp_kses_post( $total['label'] ) . '</dt><dd>' . wp_kses_post( $total['value'] ) . '</dd></div>'; } echo '</dl></section><section class="mp-card"><h2>Atualizar operação</h2><p>Status podem disparar e-mails e movimentar estoque pelas regras nativas. Reembolsos, edição financeira e estornos devem ser tratados pelo responsável técnico.</p>';
	form_start( 'order_save', 'data-confirm="Confirmar atualização do pedido? As regras de estoque e notificações do WooCommerce serão aplicadas."' ); echo '<input type="hidden" name="id" value="' . esc_attr( $order->get_id() ) . '"><input type="hidden" name="version" value="' . esc_attr( $date ? $date->getTimestamp() : 0 ) . '">';
	$choices = array( $order->get_status() => wc_get_order_status_name( $order->get_status() ) ); foreach ( Commerce::transitions( $order ) as $status ) { $choices[ $status ] = wc_get_order_status_name( $status ); } select( 'status', 'Status', $choices, $order->get_status() ); textarea( 'note', 'Nota interna (não enviada ao cliente)' );
	echo '<label class="mp-check"><input type="checkbox" name="confirm" value="1">Confirmo a mudança de status</label><label class="mp-check"><input type="checkbox" name="confirm_payment" value="1">Verifiquei o recebimento do pagamento (necessário para marcar um pedido não pago como pago)</label><button>Salvar atualização</button></form></section><section class="mp-card"><h2>Histórico recente</h2><ol class="mp-timeline">';
	foreach ( wc_get_order_notes( array( 'order_id' => $order->get_id(), 'limit' => 30, 'orderby' => 'date_created', 'order' => 'DESC' ) ) as $note ) { echo '<li><small>' . esc_html( wc_format_datetime( $note->date_created ) ) . ' · ' . esc_html( $note->customer_note ? 'Nota ao cliente' : 'Nota interna' ) . '</small><div>' . wp_kses_post( $note->content ) . '</div></li>'; } echo '</ol></section>';
}
function screen_customers() {
	echo '<h1>Clientes</h1><p>Contas de clientes registradas. Compradores convidados são consultados nos detalhes dos pedidos. Dados administrativos não são listados aqui.</p><form method="get" class="mp-filters">'; input( 'q', 'Nome ou e-mail', text( $_GET, 'q' ), 'search' ); echo '<button>Buscar</button></form>';
	$page = max( 1, number( $_GET, 'pg', 1 ) ); $args = array( 'role' => 'customer', 'number' => 20, 'paged' => $page, 'orderby' => 'registered', 'order' => 'DESC' );
	$search = text( $_GET, 'q' ); if ( $search ) { $args['search'] = '*' . $search . '*'; $args['search_columns'] = array( 'user_email', 'display_name' ); }
	$query = new \WP_User_Query( $args ); echo '<div class="mp-card mp-table"><table><thead><tr><th>Nome</th><th>E-mail</th><th></th></tr></thead><tbody>';
	foreach ( $query->get_results() as $user ) { if ( $user->has_cap( 'manage_options' ) || $user->has_cap( 'marquesano_access_panel' ) ) { continue; } echo '<tr><td>' . esc_html( $user->display_name ) . '</td><td>' . esc_html( $user->user_email ) . '</td><td><a href="' . esc_url( url( 'cliente/' . $user->ID ) ) . '">Consultar</a></td></tr>'; }
	if ( ! $query->get_results() ) { echo '<tr><td colspan="3">Nenhum cliente registrado encontrado.</td></tr>'; } echo '</tbody></table></div>'; pages( $page, (int) ceil( $query->get_total() / 20 ) );
}
function screen_customer() {
	$user = get_userdata( Router::$id ); if ( ! $user || ! in_array( 'customer', $user->roles, true ) || $user->has_cap( 'manage_options' ) || $user->has_cap( 'marquesano_access_panel' ) ) { throw new \RuntimeException( 'Cliente não encontrado.', 404 ); }
	$customer = new \WC_Customer( $user->ID ); echo '<div class="mp-heading"><h1>' . esc_html( $user->display_name ) . '</h1><a href="' . esc_url( url( 'clientes' ) ) . '">Voltar aos clientes</a></div><div class="mp-card"><h2>Informações operacionais</h2><dl class="mp-order-totals">';
	$data = array( 'E-mail' => $user->user_email, 'Telefone' => $customer->get_billing_phone(), 'Endereço de cobrança' => implode( ', ', array_filter( array( $customer->get_billing_address_1(), $customer->get_billing_address_2(), $customer->get_billing_city(), $customer->get_billing_state(), $customer->get_billing_postcode(), $customer->get_billing_country() ) ) ), 'Endereço de entrega' => implode( ', ', array_filter( array( $customer->get_shipping_address_1(), $customer->get_shipping_city(), $customer->get_shipping_state(), $customer->get_shipping_postcode() ) ) ), 'Pedidos' => $customer->get_order_count() );
	foreach ( $data as $label => $value ) { echo '<div><dt>' . esc_html( $label ) . '</dt><dd>' . esc_html( '' === $value || null === $value ? '—' : $value ) . '</dd></div>'; } echo '</dl><p>Consulta somente leitura. Alterações de conta e solicitações de privacidade devem seguir o procedimento da loja.</p></div>';
}
